-- Generated by generate.mjs. Quiesce the Speed Reading API and take a fresh backup first.
-- This is a scoped rollback, not a database restore. Questions and user history are preserved.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
SELECT pg_advisory_xact_lock(hashtext('comprehension-v1'));
LOCK TABLE speed_reading.exercises, speed_reading.reading_texts IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE comprehension_rollback_settings ON COMMIT DROP AS
SELECT (item->>'id')::uuid id, (item->>'ageGroupId')::uuid age_id, (item->>'level')::int level,
  item->>'previousTitle' old_title, item->'previousConfiguration' old_config,
  item->>'title' title, item->'configuration' config
FROM jsonb_array_elements($settings${{SETTINGS}}$settings$::jsonb) item;
CREATE TEMP TABLE comprehension_rollback_content ON COMMIT DROP AS
SELECT (item->>'id')::uuid id, (item->>'exerciseId')::uuid exercise_id,
  (item->>'ageGroupId')::uuid age_id, (item->>'level')::int level, (item->>'wordCount')::int word_count,
  item->>'title' title, item->>'content' content
FROM jsonb_array_elements($content${{CONTENT}}$content$::jsonb) item;
DO $$ BEGIN
  IF (SELECT count(*) FROM comprehension_rollback_settings)<>40
    OR (SELECT count(DISTINCT id) FROM comprehension_rollback_settings)<>40
    OR (SELECT count(*) FROM comprehension_rollback_content)<>80
    OR (SELECT count(DISTINCT id) FROM comprehension_rollback_content)<>80
    THEN RAISE EXCEPTION 'Comprehension rollback payload incomplete'; END IF;
  IF EXISTS(SELECT 1 FROM comprehension_rollback_settings s LEFT JOIN speed_reading.exercises e ON e.id=s.id
    WHERE e.id IS NULL OR e.target_age_group_id IS DISTINCT FROM s.age_id OR e.difficulty_level IS DISTINCT FROM s.level
      OR e.is_deleted OR NOT e.is_active
      OR NOT ((e.configuration_json=s.config AND e.title=s.title)
        OR (e.configuration_json=s.old_config AND e.title=s.old_title)))
    THEN RAISE EXCEPTION 'Comprehension rollback catalog changed; manual review required'; END IF;
  IF EXISTS(SELECT 1 FROM comprehension_rollback_content c LEFT JOIN speed_reading.reading_texts t ON t.id=c.id
    WHERE t.id IS NULL OR t.created_by IS DISTINCT FROM 'comprehension-v1' OR t.is_deleted
      OR t.exercise_id IS DISTINCT FROM c.exercise_id OR t.title IS DISTINCT FROM c.title
      OR t.content IS DISTINCT FROM c.content OR t.word_count IS DISTINCT FROM c.word_count
      OR t.target_age_group_id IS DISTINCT FROM c.age_id OR t.difficulty_level IS DISTINCT FROM c.level
      OR t.language IS DISTINCT FROM 'tr' OR t.category IS DISTINCT FROM 'comprehension'
      OR t.tags IS DISTINCT FROM 'comprehension-v1;original-selection'
      OR t.recommended_min_level IS DISTINCT FROM c.level OR t.recommended_max_level IS DISTINCT FROM c.level)
    THEN RAISE EXCEPTION 'Comprehension rollback content changed; manual review required'; END IF;
END $$;
UPDATE speed_reading.exercises e SET configuration_json=s.old_config,title=s.old_title,
  updated_at=now(),updated_by='comprehension-v1-rollback',version=e.version+1
FROM comprehension_rollback_settings s WHERE e.id=s.id
  AND (e.configuration_json IS DISTINCT FROM s.old_config OR e.title IS DISTINCT FROM s.old_title);
UPDATE speed_reading.reading_texts t SET is_active=false,updated_at=now(),
  updated_by='comprehension-v1-rollback',version=t.version+1
FROM comprehension_rollback_content c WHERE t.id=c.id AND t.is_active;
COMMIT;
